function prepareAspectActions(context) {
  const keys = ['victory', 'obstacle', 'story', 'gratitude', 'joke', 'personalLife'];
  if (keys.some(key => typeof context?.aspects?.flags?.[key] !== 'boolean')) throw new Error('Aspectos inválidos para roteamento.');
  const active = keys.filter(key => context.aspects.flags[key]);
  return (active.length ? active : ['none']).map(aspect => ({ ...context, flags: context.aspects.flags, aspect }));
}
return prepareAspectActions($input.first().json).map(json=>({json}));

const context=$('Executar cada aspecto true').item.json;
const result=$input.first().json;
return [{json:{...context,...result,aspect:context.aspect,errors:{...context.errors,...result.errors}}}];

function combineFinalization(items) {
  if (!items.length || !items[0].aspects) throw new Error('Finalização sem resultados de aspectos.');
  const first = items[0];
  const errors = Object.assign({}, ...items.map(item => item.errors ?? {}));
  const victory = items.find(item => item.aspect === 'victory');
  return { ok: true, generatedContents:first.generatedContents??[], generatedContentErrors:first.generatedContentErrors??[], aspects: first.aspects, diary: first.diary ?? null,
    achievements: victory?.achievements ?? [], errors,
    activeRoutes: Object.keys(first.aspects.flags).filter(key => first.aspects.flags[key]),
    actionResults: items.filter(item => item.aspect !== 'none').map(item => ({ aspect: item.aspect, status: item.errors?.brag && item.aspect === 'victory' ? 'failed' : item.aspect === 'victory' ? 'completed' : 'no_behavior' })) };
}
return [{json:combineFinalization($input.all().map(item=>item.json))}];

const context=$input.first().json;
const text=context.text;
return [{json:{text,referenceId:context.groupId,contentTitle:'Conteúdo do Diário',contentSourceIds:context.sourceIds,sourceWordCount:(text.match(/\S+/g)??[]).length}}];

function structureAutomaticContent(value, context, origin) {
  if (value.error) return { generatedContents: [], generatedContentErrors: [{ origin, referenceId: context.referenceId, message: String(value.error.message ?? value.error) }] };
  if (value.output === undefined) return { generatedContents: [], generatedContentErrors: [] }; // Switch fallback: continue normally.
  const body = typeof value.output === 'string' ? value.output.trim() : JSON.stringify(value.output, null, 2);
  if (!body) return { generatedContents: [], generatedContentErrors: [{ origin, referenceId: context.referenceId, message: 'Agent retornou conteúdo vazio.' }] };
  const now = new Date().toISOString();
  const title = (body.match(/^#{1,6}\s+(.+)$/m)?.[1] ?? context.contentTitle ?? 'Conteúdo gerado').slice(0, 150).trim();
  return { generatedContents: [{ schemaVersion: 1, origin, referenceId: context.referenceId, sourceIds: context.contentSourceIds,
    createdAt: now, updatedAt: now, title, body, sourceWordCount: context.sourceWordCount,
    wordCount: (body.match(/\S+/g) ?? []).length }], generatedContentErrors: [] };
}
const context=$("Contar palavras para conteúdo — Diário").item.json;
return [{json:structureAutomaticContent($input.first().json,context,"diario")}];
